-- Crédito Fácil: ejecutar completo en Supabase SQL Editor.
create extension if not exists pgcrypto;
create type public.app_role as enum ('admin','operator');
create type public.loan_status as enum ('draft','active','paid_off','cancelled','restructured');
create type public.installment_status as enum ('pending','paid','partial','overdue','restructured');
create type public.payment_method as enum ('cash','transfer','card','other');
create type public.interest_type as enum ('simple','declining_balance');
create type public.late_rule as enum ('daily','per_overdue_period','percent_overdue_balance');
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text not null, role app_role not null default 'operator', active boolean not null default true, created_at timestamptz not null default now());
create table public.clients (id uuid primary key default gen_random_uuid(), full_name text not null, phone text not null, email text, address text, identification text unique, birth_date date, notes text, active boolean not null default true, created_by uuid references public.profiles(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.system_settings (id boolean primary key default true check(id), currency text not null default 'MXN', default_annual_rate numeric(8,4) not null default 36, default_late_rule late_rule not null default 'daily', default_late_rate numeric(12,4) not null default 0, tolerance_days int not null default 3 check(tolerance_days>=0), company_name text, receipt_footer text, updated_at timestamptz not null default now());
insert into public.system_settings(id) values(true) on conflict do nothing;
create table public.loans (id uuid primary key default gen_random_uuid(), folio text not null unique, client_id uuid not null references public.clients(id), principal numeric(14,2) not null check(principal>0), disbursed_at date not null, first_payment_at date not null, frequency text not null check(frequency in ('weekly','biweekly','monthly','custom')), custom_days int, installments_count int not null check(installments_count>0), interest_type interest_type not null, annual_interest_rate numeric(8,4) not null check(annual_interest_rate>=0), tolerance_days int not null default 3, late_rule late_rule not null default 'daily', late_rate numeric(12,4) not null default 0, status loan_status not null default 'active', total_due numeric(14,2) not null default 0, outstanding_balance numeric(14,2) not null default 0, created_by uuid references public.profiles(id), created_at timestamptz not null default now());
create table public.installments (id uuid primary key default gen_random_uuid(), loan_id uuid not null references public.loans(id) on delete cascade, sequence_no int not null, due_date date not null, principal_due numeric(14,2) not null, ordinary_interest_due numeric(14,2) not null, late_interest_due numeric(14,2) not null default 0, paid_amount numeric(14,2) not null default 0, paid_at timestamptz, status installment_status not null default 'pending', remaining_balance numeric(14,2) not null, unique(loan_id,sequence_no));
create table public.payments (id uuid primary key default gen_random_uuid(), loan_id uuid not null references public.loans(id), client_id uuid not null references public.clients(id), paid_at timestamptz not null default now(), amount numeric(14,2) not null check(amount>0), late_applied numeric(14,2) not null default 0, interest_applied numeric(14,2) not null default 0, principal_applied numeric(14,2) not null default 0, method payment_method not null, reference text, notes text, received_by uuid references public.profiles(id), allow_overpayment boolean not null default false, created_at timestamptz not null default now());
create table public.payment_allocations (payment_id uuid references public.payments(id) on delete cascade, installment_id uuid references public.installments(id), late_amount numeric(14,2) not null default 0, interest_amount numeric(14,2) not null default 0, principal_amount numeric(14,2) not null default 0, primary key(payment_id,installment_id));
create table public.audit_log (id bigint generated always as identity primary key, actor_id uuid references public.profiles(id), action text not null, entity_type text not null, entity_id uuid, before_data jsonb, after_data jsonb, created_at timestamptz not null default now());
create table public.receipts (id uuid primary key default gen_random_uuid(), payment_id uuid not null unique references public.payments(id), receipt_number text not null unique, issued_at timestamptz not null default now(), snapshot jsonb not null default '{}');
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from profiles where id=auth.uid() and role='admin' and active) $$;
create or replace function public.can_access() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from profiles where id=auth.uid() and active) $$;
create sequence if not exists public.loan_folio_seq;
create or replace function public.generate_folio() returns text language plpgsql as $$ begin return 'CR-'||to_char(current_date,'YYYY')||'-'||lpad(nextval('public.loan_folio_seq')::text,5,'0'); end $$;
create or replace function public.apply_late_fees(p_loan uuid,p_today date default current_date) returns void language plpgsql security definer set search_path=public as $$ declare l record; i record; overdue_days int; added numeric; begin select * into l from loans where id=p_loan; for i in select * from installments where loan_id=p_loan and status not in ('paid','restructured') and due_date+l.tolerance_days<p_today loop overdue_days:=p_today-(i.due_date+l.tolerance_days); added:=case l.late_rule when 'daily' then l.late_rate*overdue_days when 'per_overdue_period' then l.late_rate when 'percent_overdue_balance' then ((i.principal_due+i.ordinary_interest_due-i.paid_amount)*l.late_rate/100) else 0 end; update installments set late_interest_due=greatest(late_interest_due,round(added,2)),status='overdue' where id=i.id; end loop; end $$;
create or replace function public.register_payment(p_loan uuid,p_amount numeric,p_method payment_method,p_reference text default null,p_notes text default null,p_paid_at timestamptz default now()) returns uuid language plpgsql security definer set search_path=public as $$ declare p uuid:=gen_random_uuid(); i record; rem numeric:=p_amount; latep numeric:=0; intp numeric:=0; princp numeric:=0; x numeric; begin perform apply_late_fees(p_loan,p_paid_at::date); if p_amount>(select outstanding_balance+coalesce((select sum(late_interest_due) from installments where loan_id=p_loan),0) from loans where id=p_loan) and not is_admin() then raise exception 'El pago excede el saldo permitido'; end if; insert into payments(id,loan_id,client_id,amount,method,reference,notes,paid_at,received_by) select p,id,client_id,p_amount,p_method,p_reference,p_notes,p_paid_at,auth.uid() from loans where id=p_loan; for i in select * from installments where loan_id=p_loan and status not in ('paid','restructured') order by due_date,sequence_no loop exit when rem<=0; x:=least(rem,greatest(0,i.late_interest_due)); rem:=rem-x;latep:=latep+x; update installments set late_interest_due=late_interest_due-x where id=i.id; x:=least(rem,greatest(0,i.ordinary_interest_due-(i.paid_amount))); rem:=rem-x;intp:=intp+x; x:=least(rem,greatest(0,i.principal_due-(greatest(0,i.paid_amount-i.ordinary_interest_due)))); rem:=rem-x;princp:=princp+x; update installments set paid_amount=paid_amount+x,paid_at=p_paid_at,status=case when paid_amount+x>=principal_due+ordinary_interest_due+late_interest_due then 'paid' when paid_amount+x>0 then 'partial' else status end where id=i.id; insert into payment_allocations values(p,i.id,0,x,0) on conflict do nothing; end loop; update payments set late_applied=latep,interest_applied=intp,principal_applied=princp where id=p; update loans set outstanding_balance=greatest(0,outstanding_balance-princp),status=case when outstanding_balance-princp<=0 then 'paid_off' else status end where id=p_loan; return p; end $$;
alter table public.profiles enable row level security; alter table public.clients enable row level security; alter table public.loans enable row level security; alter table public.installments enable row level security; alter table public.payments enable row level security; alter table public.payment_allocations enable row level security; alter table public.system_settings enable row level security; alter table public.audit_log enable row level security; alter table public.receipts enable row level security;
create policy "active users read profiles" on public.profiles for select using (can_access()); create policy "admins manage profiles" on public.profiles for all using (is_admin()) with check(is_admin());
create policy "active users access clients" on public.clients for all using (can_access()) with check(can_access()); create policy "active users access loans" on public.loans for all using (can_access()) with check(can_access()); create policy "active users access installments" on public.installments for select using(can_access()); create policy "admins update installments" on public.installments for update using(is_admin()); create policy "active users access payments" on public.payments for all using(can_access()) with check(can_access()); create policy "active users read allocations" on public.payment_allocations for select using(can_access()); create policy "admins settings" on public.system_settings for all using(is_admin()) with check(is_admin()); create policy "users read audit" on public.audit_log for select using(can_access()); create policy "users read receipts" on public.receipts for select using(can_access());
